/**
 * What can come out of a wish: every wishable character and weapon with its
 * English name, rarity and the game's item id (items.json, regenerated by
 * apps/tracker/scripts/wish-data.mjs from the game data and paimon.moe's
 * names). Keys are GOOD keys, so a stored pull points into the static
 * dictionaries (CHARACTERS / WEAPONS), whose ids never change meaning.
 *
 * The wish history API names items in the language it was asked for
 * (irminsul asks en-us) and often leaves `item_id` empty. An item is
 * "known" when its item id or its exact English name is in this table;
 * anything else (a new character before a game data bump, another
 * language) is kept as given, name, rank and type, and resolved by name on
 * read once the table knows it.
 */

import { CHARACTERS, WEAPONS, type KeyDictionary } from '../dictionary'
import { toGoodKey } from '../good'
import table from './items.json'

export type WishItemKind = 'character' | 'weapon'

export interface WishItemInfo {
  key: string
  kind: WishItemKind
  /** English, as the game writes it. */
  name: string
  rarity: number
  /** The game's item id (avatar id for characters). */
  itemId: number
}

/** A pulled item, as stored or as read back. */
export interface WishItem {
  /** GOOD key; null when nothing in the table matches. */
  key: string | null
  kind: WishItemKind | null
  /** The table's English name when known, else the name as it arrived. */
  name: string
  /** 3, 4 or 5; 0 when unknown. */
  rank: number
  /** 0 when unknown. */
  itemId: number
  /**
   * In the table by item id or exact English name: stored as a dictionary
   * id (name, rank and id derive from the table). Otherwise stored as given.
   */
  known: boolean
}

type Row = [key: string, name: string, rarity: number, itemId: number]

function index(rows: Row[], kind: WishItemKind): WishItemInfo[] {
  return rows.map(([key, name, rarity, itemId]) => ({ key, kind, name, rarity, itemId }))
}

export const WISH_ITEMS: readonly WishItemInfo[] = [
  ...index(table.characters as Row[], 'character'),
  ...index(table.weapons as Row[], 'weapon'),
]

const byKey = new Map<string, WishItemInfo>()
const byLowerKey = new Map<string, WishItemInfo>()
const byName = new Map<string, WishItemInfo>()
const byItemId = new Map<number, WishItemInfo>()
for (const info of WISH_ITEMS) {
  byKey.set(`${info.kind}:${info.key}`, info)
  if (!byLowerKey.has(info.key.toLowerCase())) byLowerKey.set(info.key.toLowerCase(), info)
  if (!byName.has(info.name)) byName.set(info.name, info)
  byItemId.set(info.itemId, info)
}

export function wishItemInfo(kind: WishItemKind, key: string): WishItemInfo | undefined {
  return byKey.get(`${kind}:${key}`)
}

export function wishItemByItemId(itemId: number): WishItemInfo | undefined {
  return byItemId.get(itemId)
}

/** The dictionary a kind's keys live in. */
export function wishDictionary(kind: WishItemKind): KeyDictionary {
  return kind === 'character' ? CHARACTERS : WEAPONS
}

const known = (info: WishItemInfo): WishItem => ({
  key: info.key,
  kind: info.kind,
  name: info.name,
  rank: info.rarity,
  itemId: info.itemId,
  known: true,
})

/** "Character" / "Weapon" in the languages the API answers most (others: null). */
export function wishItemKind(type: string): WishItemKind | null {
  const t = type.trim().toLowerCase()
  if (t === 'character' || t === '角色') return 'character'
  if (t === 'weapon' || t === '武器') return 'weapon'
  return null
}

/** A table item, from a GOOD key in any case (paimon.moe's ids, spelled loosely). */
export function wishItemByLooseKey(key: string): WishItemInfo | undefined {
  return byLowerKey.get(toGoodKey(key).toLowerCase())
}

/**
 * Resolves an item as a record names it: by item id, then by exact English
 * name; else kept as given (with the table's key, kind and rarity when its
 * GOOD key matches one, for reading only).
 */
export function resolveWishItem(input: {
  name: string
  itemType?: string
  rank?: number
  itemId?: number
}): WishItem {
  const byId = input.itemId ? byItemId.get(input.itemId) : undefined
  if (byId) return known(byId)
  const exact = byName.get(input.name)
  const kind = input.itemType ? wishItemKind(input.itemType) : null
  if (exact && (kind === null || kind === exact.kind)) return known(exact)
  const loose = byLowerKey.get(toGoodKey(input.name).toLowerCase())
  const match = loose && (kind === null || kind === loose.kind) ? loose : undefined
  return {
    key: match?.key ?? null,
    kind: kind ?? match?.kind ?? null,
    name: input.name,
    rank: input.rank || match?.rarity || 0,
    itemId: input.itemId || match?.itemId || 0,
    known: false,
  }
}

/** A stored dictionary reference, read back. */
export function knownWishItem(kind: WishItemKind, key: string): WishItem {
  const info = byKey.get(`${kind}:${key}`)
  if (info) return known(info)
  // In the dictionary but no longer in the table: should not happen (a test
  // pins the table inside the dictionaries); spell the key out.
  return {
    key,
    kind,
    name: key.replace(/([a-z0-9])([A-Z])/g, '$1 $2'),
    rank: 0,
    itemId: 0,
    known: true,
  }
}

/** The English item type the API and UIGF write. */
export function wishItemTypeLabel(kind: WishItemKind | null): string {
  return kind === 'weapon' ? 'Weapon' : kind === 'character' ? 'Character' : ''
}
